fn prime_factors(n: Int) -> (Int, Int, Option<Int>) {
    let mut divisors = vec()
    let mut sum = 0
    let mut max_div = None
    for i in range(2, n + 1) {
        if n % i == 0 {
            push(divisors, i)
            sum += i
            max_div = Some(i)
        }
    }
    (len(divisors), sum, max_div)
}
fn is_prime(n: Int) -> Bool {
    if n <= 1 { return false }
    for i in range(2, n) {
        if n % i == 0 { return false }
    }
    true
}

