        match fig {
            Rect(r) => {
                let a = area_rect(r)
                print_str("rect")
                print(a)
                total_area += a
            },
            Square(s) => {
                let a = area_square(s)
                print_str("square")
                print(a)
                total_area += a
            },
            Circle(c) => {
                let a = area_circle(c)
                print_str("circle")
                print(a)
                total_area += a
            }
        }
